# SPDX-FileCopyrightText: 2026 madfam-org
# requires: console_shell
"""commons-lib/hardware/console_io.py — what a desktop device takes in and plugs into.

Components (plan §2.3, Media interfaces and Connectors): `media_cartridge_slot`
(the plan's `cartridge_slot`, consuming a `media_envelope`; renamed because
`connectors.cartridge_slot` already exists and module names may not collide),
`card_slot`, `disc_lid` + `disc_lid_seat`, `disc_tray` + `disc_tray_bay`,
`slot_loader`, `slot_door`, `slot_blank`, `slide_switch`, `controller_port`,
`port_row`.

Every component is built in a FACE FRAME (`console_shell.face_plane`): local X
along the face, local Y up the face, local +Z outward. A tool spans
`overshoot` outside the frame's plane to `depth` inside it, so no cut ends on a
face. Solids (a lid, a tray, a door) are returned already posed. Each takes its
OWN parameter dict, reads no manifest global and knows no assembly.

Opening sizes for connector kinds are ARCHETYPE constants (below): clearance
openings, never a connector's drawing. The keystone's standard parts
(`dsub-de9-female`, `hdmi-type-a-receptacle`, …) are the facts a later
revision reads once `SPEC_PIN` carries them.

Inlined, never imported: `tools/inline_parts.py` copies this text into every
family `main.py` that declares it (ruling R2 on gate H8).
"""

import math

import cadquery as cq

#: Controller-port clearance openings (width, height) in mm. Archetype.
CONTROLLER_PORT_OPENINGS = {
    "de9": (19.0, 10.5),
    "round_din": (13.0, 13.0),
    "proprietary": (16.0, 9.0),
    "usb_a": (13.4, 6.0),
}
#: Rear-panel clearance openings (shape, width, height) in mm, per kind. Archetype.
PORT_OPENINGS = {
    "rf_f": ("round", 9.5, 9.5), "rca": ("round", 8.5, 8.5),
    "multi_av": ("rect", 32.0, 7.0), "hdmi": ("rect", 15.0, 6.0),
    "cord": ("round", 7.0, 7.0), "barrel": ("round", 9.0, 9.0),
    "iec_c7": ("rect", 11.0, 6.5), "iec_c8": ("rect", 11.0, 6.5),
    "iec_c13": ("rect", 28.0, 20.0), "proprietary": ("rect", 12.0, 8.0),
    "ethernet": ("rect", 16.0, 13.5), "usb_a": ("rect", 13.4, 6.0),
    "expansion": ("rect", 40.0, 8.0),
}
#: Thickness of an optical disc (CD/DVD/BD, ISO/IEC 10149 and successors).
DISC_THICKNESS = 1.2


def _box_tool(plane, w, h, depth, overshoot, u=0.0, v=0.0):
    return (
        cq.Workplane(plane).workplane(offset=overshoot).center(u, v)
        .rect(w, h).extrude(-(depth + overshoot))
    )


def media_cartridge_slot(p):
    """A cartridge mouth sized from the medium it takes (the tool).

    CDG consumed: `media_envelope` (the `plug-in-media` family's shell width x
    thickness x insertion depth). CDG exposed: `media_slot` = that envelope plus
    `clearance` on every side; the cavity is `insert_depth + clearance` deep.

    p: frame, media_width, media_thickness, insert_depth, clearance, overshoot,
       extra_depth (the face's own variation over the footprint)
    """
    c = p["clearance"]
    return _box_tool(face_plane(p["frame"]), p["media_width"] + 2 * c,
                     p["media_thickness"] + 2 * c,
                     p["insert_depth"] + c + p["extra_depth"], p["overshoot"])


def card_slot(p):
    """A card slot (a HuCard-type monolithic card, a memory card): a thin mouth
    plus a finger scoop below it, one tool.

    CDG exposed: `media_slot` (card form).

    p: frame, card_width, card_thickness, insert_depth, clearance, scoop_radius,
       overshoot
    """
    plane = face_plane(p["frame"])
    c = p["clearance"]
    mouth = _box_tool(plane, p["card_width"] + 2 * c, p["card_thickness"] + 2 * c,
                      p["insert_depth"] + c, p["overshoot"])
    r = p["scoop_radius"]
    scoop = (
        cq.Workplane(plane).center(0.0, -(p["card_thickness"] / 2.0 + c + r * 0.6))
        .circle(r).extrude(-r * 0.5)
    )
    scoop = scoop.union(cq.Workplane(plane).center(
        0.0, -(p["card_thickness"] / 2.0 + c + r * 0.6)).circle(r).extrude(p["overshoot"]))
    return mouth.union(scoop)


def disc_lid_seat(p):
    """The recess a hinged disc lid closes into, plus the disc well (the tool).

    CDG exposed: `revolute_axis` (the lid's rear edge) — the id `hinge-hyperobject`
    declares. The well is `disc_diameter + 4` across.

    p: frame, lid_diameter, seat_depth, disc_diameter, well_depth, overshoot
    """
    plane = face_plane(p["frame"])
    seat = (
        cq.Workplane(plane).workplane(offset=p["overshoot"]).circle(p["lid_diameter"] / 2.0)
        .extrude(-(p["seat_depth"] + p["overshoot"]))
    )
    well = (
        cq.Workplane(plane).workplane(offset=-p["seat_depth"] + 0.5)
        .circle((p["disc_diameter"] + 4.0) / 2.0).extrude(-(p["well_depth"] + 0.5))
    )
    return seat.union(well)


def disc_lid(p):
    """A round hinged disc lid, posed at `angle` (0 closed, opening upward).

    CDG exposed: `revolute_axis` (local Y = +radius, the rear edge). The lid's top
    is `drop` below the frame plane when closed; `gap` is the running clearance.

    p: frame, lid_diameter, thickness, gap, drop, angle
    """
    plane = face_plane(p["frame"])
    r = p["lid_diameter"] / 2.0 - p["gap"]
    lid = (
        cq.Workplane(plane).workplane(offset=-p["drop"]).circle(r)
        .extrude(-(p["thickness"] - p["gap"]))
    )
    a = plane.toWorldCoords((0.0, r, -p["drop"]))
    b = plane.toWorldCoords((1.0, r, -p["drop"]))
    return lid.rotate(a.toTuple(), b.toTuple(), -p["angle"])


def disc_tray_bay(p):
    """The front opening and cavity a disc tray runs in (the tool).

    CDG exposed: `prismatic_axis` (the frame's normal).

    p: frame, width, height, depth, overshoot
    """
    return _box_tool(face_plane(p["frame"]), p["width"], p["height"], p["depth"],
                     p["overshoot"])


def disc_tray(p):
    """A disc tray, slid out by `extension` x `travel` along the frame normal.

    CDG exposed: `prismatic_axis`; carries a disc pocket on its top face.

    p: frame, width, height, depth, gap, disc_diameter, pocket_depth, extension,
       travel
    """
    plane = face_plane(p["frame"])
    g = p["gap"]
    w, h, d = p["width"] - 2 * g, p["height"] - 2 * g, p["depth"] - g
    tray = cq.Workplane(plane).rect(w, h).extrude(-d)
    # The pocket: a disc-sized cylinder standing on the tray's top face (local +Y).
    top = cq.Plane(origin=plane.toWorldCoords((0.0, h / 2.0, -d / 2.0)),
                   xDir=plane.xDir, normal=plane.yDir)
    pocket = (
        cq.Workplane(top).workplane(offset=1.0).circle((p["disc_diameter"] + 2.0) / 2.0)
        .extrude(-(p["pocket_depth"] + 1.0))
    )
    tray = tray.cut(pocket)
    move = plane.zDir.multiply(p["extension"] * p["travel"])
    return tray.translate(move.toTuple())


def slot_loader(p):
    """A slot-loading disc mouth: a bevelled lip over a disc-wide cavity (the tool).

    CDG exposed: `media_slot` (disc form).

    p: frame, disc_diameter, clearance, depth, overshoot
    """
    plane = face_plane(p["frame"])
    w = p["disc_diameter"] + 2 * p["clearance"]
    h = DISC_THICKNESS + 2 * p["clearance"]
    cavity = _box_tool(plane, w, h, p["depth"], p["overshoot"])
    lip = _box_tool(plane, w + 4.0, h + 2.0, 1.5, p["overshoot"])
    return cavity.union(lip)


def slot_door(p):
    """A hinged door (or a pair of flaps) over a media mouth, posed at `angle`.

    CDG exposed: `revolute_axis` along its +Y edge. `flaps` splits the plate down
    the middle with a groove that stops halfway through, so it stays ONE solid.

    p: frame, kind ("door"|"flaps"), width, height, margin, thickness, angle
    """
    plane = face_plane(p["frame"])
    w, h, t = p["width"] + 2 * p["margin"], p["height"] + 2 * p["margin"], p["thickness"]
    plate = cq.Workplane(plane).rect(w, h).extrude(t)
    if p["kind"] == "flaps":
        groove = (
            cq.Workplane(plane).workplane(offset=t + 1.0).rect(1.0, h + 2.0)
            .extrude(-(t / 2.0 + 1.0))
        )
        plate = plate.cut(groove)
    a = plane.toWorldCoords((0.0, h / 2.0, 0.0))
    b = plane.toWorldCoords((1.0, h / 2.0, 0.0))
    return plate.rotate(a.toTuple(), b.toTuple(), -p["angle"])


def slot_blank(p):
    """A blank that closes a mouth: a plug, with or without an outside flange.

    CDG consumed: `media_slot`. Without a flange it is a flush bay cover.

    p: frame, width, height, plug_depth, gap, flange, flange_margin,
       flange_thickness
    """
    plane = face_plane(p["frame"])
    g = p["gap"]
    plug = (
        cq.Workplane(plane).rect(p["width"] - 2 * g, p["height"] - 2 * g)
        .extrude(-p["plug_depth"])
    )
    if not p["flange"]:
        return plug
    m = p["flange_margin"]
    flange = (
        cq.Workplane(plane).workplane(offset=-0.2)
        .rect(p["width"] + 2 * m, p["height"] + 2 * m).extrude(p["flange_thickness"] + 0.2)
    )
    return plug.union(flange)


def slide_switch(p):
    """A row of slide-switch slots (the VCS-type console panel), one 2-D region
    extruded once (the tool).

    CDG exposed: `switch_seat`. Each slot runs along local Y.

    p: frame, count, pitch, length, width, depth, overshoot
    """
    plane = face_plane(p["frame"])
    n = int(p["count"])
    pts = [((i - (n - 1) / 2.0) * p["pitch"], 0.0) for i in range(n)]
    return (
        cq.Workplane(plane).workplane(offset=p["overshoot"]).pushPoints(pts)
        .slot2D(p["length"], p["width"], 90).extrude(-(p["depth"] + p["overshoot"]))
    )


def controller_port(p):
    """A row of controller-port openings of one kind (the tool).

    CDG exposed: `controller_port_face`. `de9` is a D-shaped trapezoid (the
    Atari/Sega joystick port; its facts are the keystone's `dsub-de9-female`),
    `round_din` a circle, `proprietary` and `usb_a` rectangles. Sizes are the
    archetype's clearance openings, CONTROLLER_PORT_OPENINGS.

    p: frame, kind, count, pitch, depth, overshoot
    """
    plane = face_plane(p["frame"])
    w, h = CONTROLLER_PORT_OPENINGS[p["kind"]]
    n = int(p["count"])
    wp = cq.Workplane(plane).workplane(offset=p["overshoot"])
    pts = [((i - (n - 1) / 2.0) * p["pitch"], 0.0) for i in range(n)]
    total = p["depth"] + p["overshoot"]
    if p["kind"] == "round_din":
        return wp.pushPoints(pts).circle(w / 2.0).extrude(-total)
    if p["kind"] == "de9":
        inset = h * math.tan(math.radians(10.0))
        out = None
        for x, y in pts:
            trap = (
                cq.Workplane(plane).workplane(offset=p["overshoot"])
                .polyline([(x - w / 2.0, y + h / 2.0), (x + w / 2.0, y + h / 2.0),
                           (x + w / 2.0 - inset, y - h / 2.0),
                           (x - w / 2.0 + inset, y - h / 2.0)]).close().extrude(-total)
            )
            out = trap if out is None else out.union(trap)
        return out
    return wp.pushPoints(pts).rect(w, h).extrude(-total)


def port_row(p):
    """A row of connector openings along a face, laid left to right (the tool).

    CDG exposed: `port_cutout`, one per opening. `items` are (shape, width,
    height) — PORT_OPENINGS rows, or any — placed from `start_u` with `gap`
    between them, all centred at height `v`. The cut reaches `depth` inside.

    p: frame (origin at the row's start), items, gap, depth, overshoot
    """
    plane = face_plane(p["frame"])
    out = None
    u = 0.0
    for shape, w, h in p["items"]:
        wp = cq.Workplane(plane).workplane(offset=p["overshoot"]).center(u + w / 2.0, 0.0)
        sk = wp.circle(w / 2.0) if shape == "round" else wp.rect(w, h)
        hole = sk.extrude(-(p["depth"] + p["overshoot"]))
        out = hole if out is None else out.union(hole)
        u += w + p["gap"]
    return out
# END commons-lib/hardware/console_io.py@bf62d4a2fd07f4d31a3c5e2712c1b6dcbc106dd2


# ═════════════════════════════════════════════════════════════════════════════
# ASSEMBLY — the only code that maps this manifest's parameters onto component
# dicts. Fixed numbers below are archetype constructions, named once.
# ═════════════════════════════════════════════════════════════════════════════

BITE = 0.2          # every fuse overlaps by this much (the canon's bite)
OVER = 1.0          # every cut tool starts this far outside its face
GAP = 0.3           # running clearance between a closure and its opening
COVER_GAP = 0.2     # air between a side cover and the core: never a shared face
PORT_DEPTH = 6.0    # how far a port opening bites into its face
BUTTON_RADIUS = 5.0
LED_RADIUS = 1.5
LID_THICKNESS = 6.0
WELL_DEPTH = 4.0
DOOR_THICKNESS = 2.0
DOOR_MARGIN = 4.0
CARD_SIZE = (54.0, 7.0, 40.0)   # memory-card slot: width, thickness, insertion
HOST_LINK = (60.0, 10.0, 12.0)  # role addon: the link a host sits on
REAR_GAP = 8.0


def _secs(h_total, depth, drop):
    """Base-run sections [[y_from_front, height]] for the body plan."""
    fb = min(max(front_break_y, 0.0), depth) * depth / body_depth
    if body_plan == "wedge":
        s = [[0.0, front_height], [fb, front_height], [depth, h_total]]
    elif body_plan == "upright":
        s = [[0.0, h_total], [fb, h_total], [depth, rear_height]]
    elif body_plan == "stepped":
        s = [[0.0, h_total - upper_tier_height], [depth, h_total - upper_tier_height]]
    else:
        s = [[0.0, h_total], [depth, h_total]]
    if fb < 1.0 and len(s) == 3:
        s = [s[0], s[2]]
    return [[y, h - drop] for y, h in s]


def context(core):
    """Dimensions of the full outline (core=False) or of the covered core."""
    n = side_cover_count if core else 0
    ov = side_cover_overhang if n else 0.0
    w = body_width - n * (side_cover_thickness + COVER_GAP)
    cx = -(side_cover_thickness + COVER_GAP) / 2.0 if n == 1 else 0.0
    d = body_depth - 2.0 * ov
    ctx = {"w": w, "d": d, "cx": cx, "top": body_height - ov, "secs": _secs(body_height, d, ov)}
    ctx["tier"] = None
    if body_plan == "stepped":
        y0 = min(front_break_y, body_depth) * d / body_depth
        y1 = d - upper_tier_inset_y
        ctx["tier"] = {"w": w - 2.0 * upper_tier_inset_x, "d": y1 - y0,
                       "cy": -d / 2.0 + (y0 + y1) / 2.0, "y0": y0, "y1": y1,
                       "bottom": ctx["secs"][0][1] - crown - BITE}
    return ctx


def body_dict(ctx, inset=0.0):
    t = inset
    return {
        "width": ctx["w"] - 2 * t, "depth": ctx["d"] - 2 * t,
        "sections": [[y * (ctx["d"] - 2 * t) / ctx["d"], h - 2 * t] for y, h in ctx["secs"]],
        "crown": crown, "draft_deg": side_draft_deg, "concavity": side_concavity,
        "corner_radius_top": max(corner_radius_top - t, 0.0),
        "edge_chamfer": 0.0 if t else edge_chamfer,
        "corner_radius_plan": max(corner_radius_vertical - t, 0.0),
        "skew_deg": plan_skew_deg, "center_x": ctx["cx"], "center_y": 0.0, "base_z": t,
    }


def tier_dict(ctx, inset=0.0):
    tr = ctx["tier"]
    return {
        "width": tr["w"] - 2 * inset, "depth": tr["d"] - 2 * inset,
        "top_z": ctx["top"] - inset, "bottom_z": tr["bottom"] - (inset + 1.0 if inset else 0.0),
        "crown": crown, "draft_deg": side_draft_deg,
        "corner_radius_top": max(corner_radius_top - inset, 0.0),
        "corner_radius_plan": max(corner_radius_vertical - inset, 0.0),
        "skew_deg": plan_skew_deg, "center_x": ctx["cx"], "center_y": tr["cy"],
    }


def outline(ctx):
    """The fused outline: base run + tier (one solid)."""
    solid = shell_body(body_dict(ctx)).val()
    if ctx["tier"] is not None:
        solid = solid.fuse(upper_tier(tier_dict(ctx)).val()).clean()
    return solid


def surf_top(ctx, x, y):
    yf = min(max(y + ctx["d"] / 2.0, 0.0), ctx["d"])
    secs = ctx["secs"]
    h = secs[-1][1]
    for (y0, h0), (y1, h1) in zip(secs, secs[1:]):
        if yf <= y1:
            h = h0 + (h1 - h0) * (yf - y0) / max(y1 - y0, 1e-9)
            break
    h -= crown * min(((x - ctx["cx"]) / (ctx["w"] / 2.0)) ** 2, 1.0)
    tr = ctx["tier"]
    if tr and abs(x - ctx["cx"]) < tr["w"] / 2.0 and tr["y0"] <= yf <= tr["y1"]:
        h = max(h, ctx["top"] - crown * ((x - ctx["cx"]) / (tr["w"] / 2.0)) ** 2)
    return h


def frame(ctx, face, u, v):
    return face_frame({"face": face, "u": u, "v": v, "width": ctx["w"], "depth": ctx["d"],
                       "top": ctx["top"], "center_x": ctx["cx"]})


def extra(ctx, face, u, v, hu, hv):
    """How far inside the outer plane the real surface lies, at worst, over a footprint."""
    tan_s = math.tan(math.radians(plan_skew_deg))
    if face == "top":
        return ctx["top"] - min(surf_top(ctx, u + i * hu, v + j * hv)
                                for i in (-1, 0, 1) for j in (-1, 0, 1))
    if face == "front":
        return max(v + hv, 0.0) * tan_s
    if face == "rear":
        return max(ctx["secs"][-1][1] - max(v - hv, 0.0), 0.0) * tan_s
    if face in ("left", "right"):
        return max(v + hv, 0.0) * math.tan(math.radians(side_draft_deg)) + side_concavity
    return 0.0


def disc_frame(ctx):
    """The front frame a tray or slot loader sits in: turned upright (local X up)
    on a body taller than it is wide, as a standing console's drive is."""
    fr = frame(ctx, "front", ctx["cx"], tray_center_z)
    if body_height > body_width:
        fr["x_dir"] = (0, 0, 1)
    return fr


def rect_tool(ctx, face, u, v, w, h, depth):
    plane = face_plane(frame(ctx, face, u, v))
    total = depth + extra(ctx, face, u, v, w / 2.0, h / 2.0) + OVER
    return cq.Workplane(plane).workplane(offset=OVER).rect(w, h).extrude(-total)


def yz_port(ctx, face, x, z, shape, w, h):
    """A front or rear opening through the existing connectors.port_receptacle."""
    s = 1.0 if face == "rear" else -1.0
    depth = PORT_DEPTH + extra(ctx, face, x, z, w / 2.0, h / 2.0) + OVER
    return port_receptacle({
        "shape": shape, "width": w, "height": h, "depth": depth, "radius": w / 2.0,
        "center_x": x, "center_y": s * (ctx["d"] / 2.0 + OVER - depth / 2.0), "center_z": z,
    })


def mouth(ctx):
    """(face, u, v, width, thickness) of a slot-type medium's opening."""
    mk = media_kind
    if mk in ("cart_top", "disc_and_cart", "none"):
        thick = media_width * 0.6 if mk == "none" else media_thickness
        return "top", slot_center_x, slot_center_y, media_width, thick
    if mk == "disc_slot":
        return "front", ctx["cx"], tray_center_z, disc_diameter, DISC_THICKNESS
    return ("rear" if mk == "cart_rear" else "front"), slot_center_x, slot_center_z, \
        media_width, media_thickness


def media_tools(ctx):
    """The cut tools of the media interface (the `none` kind is a flush bay pocket)."""
    mk, c = media_kind, slot_clearance
    face, u, v, w, t = mouth(ctx)
    tools = []
    if mk in ("cart_top", "disc_and_cart", "none", "cart_front", "cart_rear"):
        tools.append(media_cartridge_slot({
            "frame": frame(ctx, face, u, v), "media_width": w, "media_thickness": t,
            "insert_depth": 1.5 if mk == "none" else media_insert_depth, "clearance": c,
            "overshoot": OVER, "extra_depth": extra(ctx, face, u, v, w / 2.0 + c, t / 2.0 + c)}))
    if mk == "card_front":
        tools.append(card_slot({"frame": frame(ctx, face, u, v), "card_width": w,
                                "card_thickness": t, "insert_depth": media_insert_depth,
                                "clearance": c, "scoop_radius": 6.0, "overshoot": OVER}))
    if mk in ("disc_lid", "disc_and_cart"):
        r = lid_diameter / 2.0
        tools.append(disc_lid_seat({
            "frame": frame(ctx, "top", lid_center_x, lid_center_y), "lid_diameter": lid_diameter,
            "seat_depth": extra(ctx, "top", lid_center_x, lid_center_y, r, r) + LID_THICKNESS,
            "disc_diameter": disc_diameter, "well_depth": WELL_DEPTH, "overshoot": OVER}))
    if mk == "disc_tray":
        tools.append(disc_tray_bay({"frame": disc_frame(ctx), "width": tray_width,
                                    "height": tray_height, "depth": disc_diameter + 6.0 + GAP,
                                    "overshoot": OVER}))
    if mk == "disc_slot":
        tools.append(slot_loader({"frame": disc_frame(ctx), "disc_diameter": disc_diameter,
                                  "clearance": c, "depth": disc_diameter * 0.6, "overshoot": OVER}))
    return tools


def closure_part(ctx):
    """The part that closes the media opening, posed by lid_angle / tray_extension."""
    mk, c = media_kind, slot_clearance
    if mk in ("disc_lid", "disc_and_cart"):
        return disc_lid({"frame": frame(ctx, "top", lid_center_x, lid_center_y),
                         "lid_diameter": lid_diameter, "thickness": LID_THICKNESS, "gap": GAP,
                         "drop": ctx["top"] - surf_top(ctx, lid_center_x, lid_center_y),
                         "angle": lid_angle})
    if mk == "disc_tray":
        return disc_tray({"frame": disc_frame(ctx), "width": tray_width, "height": tray_height,
                          "depth": disc_diameter + 6.0, "gap": GAP, "disc_diameter": disc_diameter,
                          "pocket_depth": 1.5, "extension": tray_extension,
                          "travel": disc_diameter + 10.0})
    face, u, v, w, t = mouth(ctx)
    fr = disc_frame(ctx) if mk == "disc_slot" else frame(ctx, face, u, v)
    if face == "top":   # sit on the real surface, not the top plane
        fr["origin"] = (u, v, surf_top(ctx, u, v))
    w, h = w + 2 * c, t + 2 * c
    if mk == "none":
        return slot_blank({"frame": fr, "width": w, "height": h, "plug_depth": 1.5 - GAP,
                           "gap": GAP, "flange": False, "flange_margin": 0.0, "flange_thickness": 0.0})
    if slot_door_kind in ("door", "flaps") and mk.startswith("cart"):
        return slot_door({"frame": fr, "kind": slot_door_kind, "width": w, "height": h,
                          "margin": DOOR_MARGIN, "thickness": DOOR_THICKNESS, "angle": lid_angle})
    return slot_blank({"frame": fr, "width": w, "height": h, "plug_depth": min(10.0, media_insert_depth),
                       "gap": min(GAP, h / 4.0), "flange": True, "flange_margin": 3.0,
                       "flange_thickness": 2.0})


def panel_tools(ctx):
    """Power, reset, LEDs and slide switches (on the top shelf of a wedge or a
    stepped body, else on the front face), front buttons, front USB, memory-card
    slots and the eject button."""
    tools, hw = [], ctx["w"] / 2.0
    margin = min(max(corner_radius_vertical, 0.0) + 15.0, hw * 0.3)
    xs = [ctx["cx"] + hw - margin - BUTTON_RADIUS, ctx["cx"] + hw - margin - 4.5 * BUTTON_RADIUS]
    leds = [ctx["cx"] - hw + margin + i * 4 * LED_RADIUS for i in range(panel_led_count)]
    face = "top" if body_plan in ("wedge", "stepped") else "front"
    pv = -ctx["d"] / 2.0 + panel_center_y if face == "top" else ctx["secs"][0][1] * 0.7
    depth = 2.0 + extra(ctx, face, ctx["cx"], pv, hw, 12.0)
    if panel_switch_count > 0:
        tools.append(slide_switch({"frame": frame(ctx, face, ctx["cx"], pv),
                                   "count": panel_switch_count, "pitch": panel_switch_pitch,
                                   "length": 18.0 if face == "top" else 12.0, "width": 5.0,
                                   "depth": depth, "overshoot": OVER}))
    if power_control == "slide" and face == "top":
        tools.append(slide_switch({"frame": frame(ctx, face, xs[0], pv), "count": 1, "pitch": 0.0,
                                   "length": 18.0, "width": 6.0, "depth": depth, "overshoot": OVER}))
    elif power_control != "push":
        tools.append(rect_tool(ctx, face, xs[0], pv, 14.0, 9.0, 0.5 if power_control == "touch" else 2.0))
    rounds = ([(xs[0], BUTTON_RADIUS)] if power_control == "push" else [])
    rounds += [(xs[1], BUTTON_RADIUS * 0.8)] * int(reset_present) + [(x, LED_RADIUS) for x in leds]
    for x, r in rounds:
        if face == "top":   # the existing controls.button_row, one seat each
            tools.append(button_row({"count": 1, "first_center_x": x, "pitch_x": 0.0,
                                     "center_y": pv, "radius": r, "recess_depth": 2 * depth + OVER,
                                     "cut_center_z": ctx["top"]}))
        else:
            tools.append(yz_port(ctx, "front", x, pv, "round", 2 * r, 0))
    fz = ctx["secs"][0][1] * 0.3
    for i in range(front_button_count):
        tools.append(yz_port(ctx, "front", ctx["cx"] + hw * 0.35 + i * 3 * BUTTON_RADIUS, fz,
                             "round", 1.6 * BUTTON_RADIUS, 0))
    for i in range(usb_port_count_front):
        tools.append(yz_port(ctx, "front", ctx["cx"] + hw * 0.6 + i * 18.0, fz, "rect", 13.4, 6.0))
    for i in range(memory_card_count):
        u = ctx["cx"] - hw * 0.5 + (i - (memory_card_count - 1) / 2.0) * controller_port_pitch
        tools.append(card_slot({"frame": frame(ctx, "front", u, controller_port_center_z + 14.0),
                                "card_width": CARD_SIZE[0] * 0.4, "card_thickness": CARD_SIZE[1],
                                "insert_depth": CARD_SIZE[2], "clearance": 0.5,
                                "scoop_radius": 4.0, "overshoot": OVER}))
    if eject_button:
        tools.append(eject_tool(ctx))
    return tools


def eject_tool(ctx):
    mk = media_kind
    if mk in ("disc_tray", "disc_slot", "cart_front", "card_front"):
        off = (tray_width if mk == "disc_tray" else disc_diameter if mk == "disc_slot"
               else media_width) / 2.0 + 14.0
        ez = slot_center_z if mk.endswith("front") else tray_center_z
        ex, ez = (ctx["cx"], ez - off) if body_height > body_width and mk.startswith("disc") \
            else (ctx["cx"] + off, ez)
        return yz_port(ctx, "front", ex, ez, "round", 2 * LED_RADIUS + 3, 0)
    if mk in ("disc_lid", "disc_and_cart"):
        return rect_tool(ctx, "top", lid_center_x + lid_diameter / 2.0 + 10.0, lid_center_y, 8, 8, 1.5)
    return rect_tool(ctx, "top", slot_center_x + media_width / 2.0 + 12.0, slot_center_y, 8, 8, 1.5)


def io_tools(ctx):
    """Controller ports and bays, the rear port row, expansion, host link, screen."""
    tools, face = [], controller_port_face
    if controller_port_count > 0 and controller_port_kind != "none":
        u = {"front": ctx["cx"] - ctx["w"] * 0.25, "rear": ctx["cx"] + ctx["w"] * 0.25}.get(face, 0.0)
        tools.append(controller_port({
            "frame": frame(ctx, face, u, controller_port_center_z), "kind": controller_port_kind,
            "count": controller_port_count, "pitch": controller_port_pitch,
            "depth": PORT_DEPTH + extra(ctx, face, u, controller_port_center_z, 0, 6.0),
            "overshoot": OVER}))
    for i in range(controller_bays):
        bx = ctx["cx"] + (1 - 2 * i) * (ctx["w"] / 2.0 - corner_radius_vertical - bay_width / 2.0 - 5.0)
        tools.append(rect_tool(ctx, "top", bx, 0.0, bay_width, bay_length, bay_depth))
    P = PORT_OPENINGS
    row = [P[power_inlet_kind]] + [P[av_out_kind]] * av_out_count + [P["ethernet"]] * int(network_port)
    row += [P["usb_a"]] * usb_port_count_rear + [P["expansion"]] * expansion_port_count * int(
        expansion_port_face == "rear")
    row += [("round", cord_diameter + 1.0, cord_diameter + 1.0)] * hardwired_controllers
    start = ctx["cx"] - ctx["w"] / 2.0 + max(corner_radius_vertical, 0.0) + 12.0
    tools.append(port_row({"frame": frame(ctx, "rear", -start, rear_port_center_z), "items": row,
                           "gap": REAR_GAP, "overshoot": OVER,
                           "depth": PORT_DEPTH + extra(ctx, "rear", 0, rear_port_center_z, 0, 10.0)}))
    if channel_switch:
        x = start + sum(w for _, w, _ in row) + REAR_GAP * len(row) + 8.0
        tools.append(slide_switch({"frame": frame(ctx, "rear", -x, rear_port_center_z), "count": 1,
                                   "pitch": 0.0, "length": 10.0, "width": 4.0, "overshoot": OVER,
                                   "depth": 2.0 + extra(ctx, "rear", 0, rear_port_center_z, 0, 5.0)}))
    if expansion_port_face != "rear":
        ef = expansion_port_face
        for i in range(expansion_port_count):
            u = (i - 0.5 * (expansion_port_count - 1)) * 50.0
            v = ctx["d"] * 0.25 if ef == "bottom" else ctx["secs"][0][1] * 0.4
            tools.append(rect_tool(ctx, ef, u + (ctx["cx"] if ef == "bottom" else 0.0), v, 40.0, 8.0,
                                   PORT_DEPTH))
    if role == "addon":
        tools.append(rect_tool(ctx, "top", ctx["cx"], ctx["d"] / 2.0 - 25.0, *HOST_LINK))
    if screen_present:   # the existing displays.display_panel, turned onto the front face
        recess = 3.0 + extra(ctx, "front", 0.0, screen_center_z, 0.0, screen_height / 2.0) + OVER
        tool = display_panel({"width": screen_width, "height": screen_height, "recess_depth": recess,
                              "center_x": 0.0, "center_y": 0.0, "cut_center_z": 0.0})
        tools.append(tool.rotate((0, 0, 0), (1, 0, 0), 90).translate(
            (ctx["cx"], -ctx["d"] / 2.0 - OVER + recess / 2.0, screen_center_z)))
    if stand_seat_kind != "none":
        tools.append(stand_seat_tool(ctx))
    return tools


def stand_seat_tool(ctx):
    m = min(ctx["w"], ctx["d"])
    return stand_seat({"kind": stand_seat_kind, "diameter": m * 0.4, "depth": 3.0,
                       "groove_width": 6.0, "groove_pitch": ctx["w"] * 0.5,
                       "groove_length": ctx["d"] * 0.6, "center_x": ctx["cx"], "center_y": 0.0,
                       "base_z": 0.0})


def vent_tools(ctx):
    tools = []
    for face, u, v, w, h, pat, pitch, hole, depth in (
        (vent1_face, vent1_center_u, vent1_center_v, vent1_width, vent1_height, vent1_pattern,
         vent1_pitch, vent1_hole_size, vent1_depth),
        (vent2_face, vent2_center_u, vent2_center_v, vent2_width, vent2_height, vent2_pattern,
         vent2_pitch, vent2_hole_size, vent2_depth),
    ):
        if face == "none":
            continue
        tools.append(vent_field({"frame": frame(ctx, face, u, v), "pattern": pat, "width": w,
                                 "height": h, "pitch": pitch, "hole_size": hole,
                                 "depth": depth + extra(ctx, face, u, v, w / 2.0, h / 2.0),
                                 "overshoot": OVER}))
    return tools


def all_tools(ctx):
    return media_tools(ctx) + panel_tools(ctx) + io_tools(ctx) + vent_tools(ctx)


def _solids(wps):
    return [s for wp in wps for v in wp.vals() for s in v.Solids()]


def tilt(shape):
    if abs(orientation_tilt_deg) < 1e-9:
        return shape
    return shape.rotate((body_width / 2.0, 0, 0), (body_width / 2.0, 1, 0), orientation_tilt_deg)


def seam_z(ctx):
    return seam_height_ratio * min(h for _, h in ctx["secs"])


def seam_ring(ctx):
    """The seam groove's tool: a band around the body, less the body inset by it."""
    g = seam_groove
    band = cq.Workplane("XY").box(body_width + 20, body_depth + 20, g).translate((0, 0, seam_z(ctx)))
    return band.val().cut(shell_body({**body_dict(ctx), "width": ctx["w"] - 2 * g, "depth": ctx["d"] - 2 * g,
                                      "corner_radius_plan": max(corner_radius_vertical - g, 0.0)}).val())


def body_part():
    ctx = context(core=True)
    core = outline(ctx)
    adds = []
    if foot_count > 0:
        adds += _solids([foot_set({"count": foot_count, "diameter": foot_diameter,
                                   "height": foot_height, "span_x": ctx["w"] * 0.7,
                                   "span_y": ctx["d"] * 0.7, "center_x": ctx["cx"],
                                   "center_y": 0.0, "base_z": 0.0, "bite": BITE})])
    if handle_present:
        adds.append(handle({"span": handle_span, "reach": handle_reach,
                            "thickness": handle_thickness, "top_z": ctx["top"] - 3.0,
                            "rear_y": ctx["d"] / 2.0, "center_x": ctx["cx"], "bite": 2.0}).val())
    if adds:
        core = core.fuse(*adds).clean()
    tools = _solids(all_tools(ctx))
    if seam_groove > 0:
        tools.append(seam_ring(ctx))
    core = core.cut(*tools).clean()
    bodies = [core]
    if side_cover_count > 0:
        full = cq.Workplane("XY").add(outline(context(core=False)))
        sides = (1.0,) if side_cover_count == 1 else (1.0, -1.0)
        for s in sides:
            bodies.append(side_cover({"body": full, "side": s, "outer_x": s * body_width / 2.0,
                                      "thickness": side_cover_thickness,
                                      "offset": side_cover_offset}).val())
    return tilt(cq.Workplane("XY").add(cq.Compound.makeCompound(bodies)))


def envelope_part():
    return tilt(cq.Workplane("XY").add(outline(context(core=False))))


def shell_part(upper):
    ctx = context(core=True)
    t = wall_thickness
    inner = [shell_body(body_dict(ctx, t)).val()]
    if ctx["tier"] is not None:
        inner.append(upper_tier(tier_dict(ctx, t)).val())
    z = seam_z(ctx)
    big = body_width + body_depth + body_height + 100.0
    half = cq.Workplane("XY").box(big, big, big).translate((0, 0, z - big / 2.0 if upper else z + big / 2.0))
    cut = outline(ctx).cut(*inner, half.val(), *_solids(all_tools(ctx))).clean()
    return cq.Workplane("XY").add(cut)


BUILDERS = {
    "body": body_part,
    "closure": lambda: tilt(closure_part(context(core=True))),
    "envelope": envelope_part,
    "top_shell": lambda: shell_part(True),
    "bottom_shell": lambda: shell_part(False),
    "media_door": lambda: closure_part(context(core=True)),   # print-posed: never tilted
}

result = BUILDERS.get(target_part, body_part)()
